// =====================================================
// 全球客户语言路由 V1.0
// 节点名称：语言路由
// Mode：Run Once for Each Item
//
// 作用：
// 根据干净客户数据表中的 country
// 自动判断后续 WhatsApp 应该使用什么语言
//
// 注意：
// 这些字段只在当前工作流运行时临时存在，
// 不会自动写回干净客户数据表。
// =====================================================


// -----------------------------------------------------
// 1. 标准化国家
// -----------------------------------------------------

const countryRaw = String($json.country ?? "")
  .normalize("NFKC")
  .trim()
  .toLowerCase();


// -----------------------------------------------------
// 2. 辅助函数
// -----------------------------------------------------

function isCountry(...names) {
  return names.some(name =>
    countryRaw === String(name)
      .normalize("NFKC")
      .trim()
      .toLowerCase()
  );
}


// -----------------------------------------------------
// 3. 默认值
// 无法识别的国家，一律使用英语
// -----------------------------------------------------

let languageMode = "en";
let primaryLanguage = "en";
let secondaryLanguage = "";
let countryKey = "other";
let marketName = "international market";


// =====================================================
// 4. 阿拉伯语国家
// Arabic + English
// =====================================================

if (
  isCountry(
    "Saudi Arabia",
    "KSA",
    "United Arab Emirates",
    "UAE",
    "Qatar",
    "Kuwait",
    "Bahrain",
    "Oman",
    "Jordan",
    "Iraq",
    "Lebanon",
    "Yemen",
    "Syria",
    "Palestine",
    "State of Palestine",
    "Egypt"
  )
) {

  languageMode = "ar_en";
  primaryLanguage = "ar";
  secondaryLanguage = "en";

  if (isCountry("Saudi Arabia", "KSA")) {
    countryKey = "saudi";
    marketName = "Saudi jewelry market";
  }

  else if (
    isCountry(
      "United Arab Emirates",
      "UAE"
    )
  ) {
    countryKey = "uae";
    marketName = "UAE jewelry market";
  }

  else if (isCountry("Qatar")) {
    countryKey = "qatar";
    marketName = "Qatar jewelry market";
  }

  else if (isCountry("Kuwait")) {
    countryKey = "kuwait";
    marketName = "Kuwait jewelry market";
  }

  else if (isCountry("Bahrain")) {
    countryKey = "bahrain";
    marketName = "Bahrain jewelry market";
  }

  else if (isCountry("Oman")) {
    countryKey = "oman";
    marketName = "Oman jewelry market";
  }

  else if (isCountry("Egypt")) {
    countryKey = "egypt";
    marketName = "Egyptian jewelry market";
  }

  else {
    countryKey = "arab";
    marketName = "Middle East jewelry market";
  }
}


// =====================================================
// 5. 北非阿拉伯国家
// 目前统一 Arabic + English
// =====================================================

else if (
  isCountry(
    "Morocco",
    "Algeria",
    "Tunisia",
    "Libya"
  )
) {

  languageMode = "ar_en";
  primaryLanguage = "ar";
  secondaryLanguage = "en";
  countryKey = "north_africa";
  marketName = "North African jewelry market";
}


// =====================================================
// 6. 西班牙语
// Spanish + English
// =====================================================

else if (
  isCountry(
    "Spain",
    "Mexico",
    "Argentina",
    "Chile",
    "Colombia",
    "Peru",
    "Ecuador",
    "Uruguay",
    "Paraguay",
    "Bolivia",
    "Venezuela",
    "Costa Rica",
    "Panama",
    "Guatemala",
    "Honduras",
    "El Salvador",
    "Nicaragua",
    "Dominican Republic"
  )
) {

  languageMode = "es_en";
  primaryLanguage = "es";
  secondaryLanguage = "en";
  countryKey = "spanish";
  marketName = "local jewelry market";
}


// =====================================================
// 7. 法语
// French + English
// =====================================================

else if (
  isCountry(
    "France",
    "Monaco",
    "Senegal",
    "Ivory Coast",
    "Côte d'Ivoire",
    "Cameroon",
    "Benin",
    "Togo",
    "Mali",
    "Niger",
    "Burkina Faso",
    "Guinea"
  )
) {

  languageMode = "fr_en";
  primaryLanguage = "fr";
  secondaryLanguage = "en";
  countryKey = "french";
  marketName = "local jewelry market";
}


// =====================================================
// 8. 德语
// German + English
// =====================================================

else if (
  isCountry(
    "Germany",
    "Austria"
  )
) {

  languageMode = "de_en";
  primaryLanguage = "de";
  secondaryLanguage = "en";
  countryKey = "german";
  marketName = "local jewelry market";
}


// =====================================================
// 9. 意大利语
// Italian + English
// =====================================================

else if (
  isCountry(
    "Italy",
    "San Marino"
  )
) {

  languageMode = "it_en";
  primaryLanguage = "it";
  secondaryLanguage = "en";
  countryKey = "italian";
  marketName = "local jewelry market";
}


// =====================================================
// 10. 葡萄牙语
// Portuguese + English
// =====================================================

else if (
  isCountry(
    "Portugal",
    "Brazil"
  )
) {

  languageMode = "pt_en";
  primaryLanguage = "pt";
  secondaryLanguage = "en";
  countryKey = "portuguese";
  marketName = "local jewelry market";
}


// =====================================================
// 11. 土耳其语
// Turkish + English
// =====================================================

else if (
  isCountry(
    "Turkey",
    "Türkiye"
  )
) {

  languageMode = "tr_en";
  primaryLanguage = "tr";
  secondaryLanguage = "en";
  countryKey = "turkey";
  marketName = "Turkish jewelry market";
}


// =====================================================
// 12. 俄语
// Russian + English
// =====================================================

else if (
  isCountry(
    "Russia",
    "Russian Federation"
  )
) {

  languageMode = "ru_en";
  primaryLanguage = "ru";
  secondaryLanguage = "en";
  countryKey = "russia";
  marketName = "Russian jewelry market";
}


// =====================================================
// 13. 日语
// Japanese + English
// =====================================================

else if (isCountry("Japan")) {

  languageMode = "ja_en";
  primaryLanguage = "ja";
  secondaryLanguage = "en";
  countryKey = "japan";
  marketName = "Japanese jewelry market";
}


// =====================================================
// 14. 韩语
// Korean + English
// =====================================================

else if (
  isCountry(
    "South Korea",
    "Republic of Korea",
    "Korea"
  )
) {

  languageMode = "ko_en";
  primaryLanguage = "ko";
  secondaryLanguage = "en";
  countryKey = "korea";
  marketName = "Korean jewelry market";
}


// =====================================================
// 15. 印尼语
// Indonesian + English
// =====================================================

else if (isCountry("Indonesia")) {

  languageMode = "id_en";
  primaryLanguage = "id";
  secondaryLanguage = "en";
  countryKey = "indonesia";
  marketName = "Indonesian jewelry market";
}


// =====================================================
// 16. 泰语
// Thai + English
// =====================================================

else if (isCountry("Thailand")) {

  languageMode = "th_en";
  primaryLanguage = "th";
  secondaryLanguage = "en";
  countryKey = "thailand";
  marketName = "Thai jewelry market";
}


// =====================================================
// 17. 越南语
// Vietnamese + English
// =====================================================

else if (
  isCountry(
    "Vietnam",
    "Viet Nam"
  )
) {

  languageMode = "vi_en";
  primaryLanguage = "vi";
  secondaryLanguage = "en";
  countryKey = "vietnam";
  marketName = "Vietnamese jewelry market";
}


// =====================================================
// 18. 希伯来语
// Hebrew + English
// =====================================================

else if (isCountry("Israel")) {

  languageMode = "he_en";
  primaryLanguage = "he";
  secondaryLanguage = "en";
  countryKey = "israel";
  marketName = "Israeli jewelry market";
}


// =====================================================
// 19. 英语优先国家
// English only
// =====================================================

else if (
  isCountry(
    "United States",
    "USA",
    "US",
    "United Kingdom",
    "UK",
    "Great Britain",
    "Australia",
    "New Zealand",
    "Canada",
    "Ireland",
    "Singapore",
    "India",
    "Malaysia",
    "Philippines",
    "Netherlands",
    "Belgium",
    "Switzerland",
    "Sweden",
    "Norway",
    "Denmark",
    "Finland",
    "South Africa"
  )
) {

  languageMode = "en";
  primaryLanguage = "en";
  secondaryLanguage = "";
  countryKey = "english";
  marketName = "local jewelry market";
}


// -----------------------------------------------------
// 20. 将判断结果临时加入当前数据
// -----------------------------------------------------

$json.language_mode = languageMode;
$json.primary_language = primaryLanguage;
$json.secondary_language = secondaryLanguage;
$json.country_key = countryKey;
$json.market_name = marketName;
$json.is_bilingual = languageMode !== "en";


// -----------------------------------------------------
// 21. 输出
// -----------------------------------------------------

return $json;
